package me.him188.ani.app.domain.media.player.data

import kotlinx.cinterop.ExperimentalForeignApi
import kotlinx.coroutines.runBlocking
import kotlinx.io.buffered
import kotlinx.io.files.Path
import kotlinx.io.files.SystemFileSystem
import org.openani.mediamp.source.UriMediaData
import platform.AVFoundation.AVURLAsset
import platform.AVFoundation.AVMediaTypeVideo
import platform.AVFoundation.AVMediaTypeAudio
import platform.AVFoundation.AVMediaTypeSubtitle
import platform.AVFoundation.playable
import platform.AVFoundation.tracksWithMediaType
import platform.Foundation.NSTemporaryDirectory
import platform.Foundation.NSURL
import platform.Foundation.NSUUID
import kotlin.io.encoding.Base64
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFalse
import kotlin.test.assertSame
import kotlin.test.assertTrue

@OptIn(ExperimentalForeignApi::class)
class LocalPlaybackPreparationTest {
    @Test
    fun `completed MKV with subtitles becomes playable and is cleaned up`() = runBlocking {
        val input = Path(NSTemporaryDirectory() + "fixture space-${NSUUID().UUIDString}.mkv")
        SystemFileSystem.sink(input).buffered().use { it.write(Base64.decode(FIXTURE)) }
        try {
            val original = UriMediaData(NSURL.fileURLWithPath(input.toString()).absoluteString!!)
            val prepared = prepareLocalPlayback(original)
            val output = NSURL.URLWithString((prepared.data as UriMediaData).uri)!!
            try {
                val asset = AVURLAsset(output, null)
                assertTrue(asset.playable, "AVFoundation must open the prepared media")
                assertEquals(1, asset.tracksWithMediaType(AVMediaTypeVideo).size)
                assertEquals(1, asset.tracksWithMediaType(AVMediaTypeAudio).size)
                assertEquals(1, asset.tracksWithMediaType(AVMediaTypeSubtitle).size)
                assertTrue(SystemFileSystem.exists(input), "Original download is preserved")
            } finally { prepared.close() }
            assertFalse(SystemFileSystem.exists(Path(output.path!!)))
        } finally { SystemFileSystem.delete(input) }
    }

    @Test
    fun `remote MKV is not downloaded during local preparation`() = runBlocking {
        val input = UriMediaData("https://example.invalid/video.mkv")
        val prepared = prepareLocalPlayback(input)
        assertSame(input, prepared.data)
        prepared.close()
    }

    // One second of generated H264 video, AAC audio and an SRT subtitle. No external media.
    private companion object { const val FIXTURE = "" }
}
